function Blackacre.GetDeity(id)
    if not id then return nil end
    for i = 1, #Blackacre.Deities do
        if Blackacre.Deities[i].id == id then
            return Blackacre.Deities[i]
        end
    end
    return nil
end

local CLASS_ICON = {
    Cosmic = "Interface\\Icons\\inv_misc_orb_01",
    Supernatural = "Interface\\Icons\\spell_nature_wispsplode",
    Mortal = "Interface\\Icons\\inv_misc_groupneedmore",
    Demon = "Interface\\Icons\\ability_warlock_demonicempowerment",
    Undead = "Interface\\Icons\\spell_shadow_raisedead",
    Abstract = "Interface\\Icons\\inv_misc_book_09",
    Immortal = "Interface\\Icons\\spell_holy_divineprovidence",
}

function Blackacre.GetDeityIcon(deity)
    if type(deity) == "string" then
        deity = Blackacre.GetDeity(deity)
    end
    if not deity then
        return "Interface\\Icons\\inv_misc_questionmark"
    end
    local sub = (deity.sub or ""):lower()
    if sub:find("loa", 1, true) then
        return "Interface\\Icons\\inv_misc_head_troll_01"
    end
    if sub:find("titan", 1, true) then
        return "Interface\\Icons\\achievement_dungeon_ulduarraid_titan_rune"
    end
    if sub:find("naaru", 1, true) then
        return "Interface\\Icons\\inv_crystal_2"
    end
    if sub:find("wild god", 1, true) then
        return "Interface\\Icons\\ability_druid_naturalperfection"
    end
    return CLASS_ICON[deity.classification] or "Interface\\Icons\\inv_misc_questionmark"
end
